 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Sample recurring separator intersections, excluding the final boundary
    # track; the tile interior's background values are not output cells.
    def tracks(axis):
        n = len(grid) if axis == 0 else len(grid[0])
        tracks = []
        for i in range(n):
            line = grid[i] if axis == 0 else [row[i] for row in grid]
            if len(set(line)) <= 3:
                tracks.append(i)
        if len(tracks) < 2:
            return []
        step = min(b-a for a,b in zip(tracks, tracks[1:]) if b>a)
        return [x for x in tracks if (x-tracks[0]) % step == 0]
    rs, cs = tracks(0), tracks(1)
    if len(rs) < 2 or len(cs) < 2:
        return [[grid[0][0]]]
    return [[grid[r][c] for c in cs[:-1]] for r in rs[:-1]]
